INSERT IGNORE INTO `document_category` (`name`, `code`, `parent_id`, `sort`) VALUES
('消费维权', 'CONSUMER', 0, 15);
INSERT INTO `document_template` (`type`, `name`, `content`, `category`, `status`) VALUES
('COMPANY', '律师催告函', '致：${致送单位}\n\n本所接受${委托人}的委托，指派本律师就${委托事项}事宜，特函告如下：\n\n一、事实说明\n${事实说明}\n\n二、法律依据\n${法律依据}\n\n三、律师意见\n${律师意见}\n\n请贵方于收到本函之日起${期限}日内履行相应义务，否则本所将依据委托人的授权依法采取进一步法律措施。\n\n${律所名称}\n承办律师：${律师姓名}\n${日期}', '公司法务', 1),
('CRIMINAL_COMPLAINT', '取保候审申请书', '申请人：${申请人}\n被申请取保候审人：${被申请人}\n\n申请事项：\n请求对犯罪嫌疑人（被告人）${被申请人}采取取保候审强制措施。\n\n事实与理由：\n${事实与理由}\n\n申请人愿提供保证人或交纳保证金，保证被申请人随传随到。\n\n此致\n${办案机关}\n\n申请人：${申请人}\n${日期}', '刑事起诉状', 1),
('APPEAL', '刑事上诉状', '上诉人：${上诉人}\n\n上诉人因${案由}一案，不服${原审法院}（${原审案号}）判决，现提出上诉。\n\n上诉请求：\n${上诉请求}\n\n上诉理由：\n${上诉理由}\n\n此致\n${上级法院}\n\n上诉人：${上诉人}\n${日期}', '上诉状', 1),
('LABOR_ARBITRATION', '劳动仲裁答辩状', '答辩人（被申请人）：${答辩人}\n被答辩人（申请人）：${被答辩人}\n\n答辩人因劳动争议仲裁一案，提出答辩如下：\n\n${答辩意见}\n\n综上所述，请求仲裁庭依法驳回申请人的仲裁请求。\n\n此致\n${仲裁委}\n\n答辩人：${答辩人}\n${日期}', '劳动仲裁', 1),
('LABOR_ARBITRATION', '劳动合同书', '甲方（用人单位）：${甲方}\n乙方（劳动者）：${乙方}\n\n一、劳动合同期限：自${起始日期}至${终止日期}。\n二、工作内容与地点：${工作内容}\n三、劳动报酬：月工资${工资}元。\n四、社会保险：甲方依法为乙方缴纳社会保险。\n\n甲方（盖章）：\n乙方（签字）：\n${日期}', '劳动仲裁', 1),
('MARRIAGE', '分居协议书', '甲方：${甲方}\n乙方：${乙方}\n\n双方因感情不和，经协商决定分居，达成如下协议：\n\n一、分居期限：自${起始日期}起。\n二、子女抚养安排：${子女抚养}\n三、财产与债务安排：${财产安排}\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '婚姻家庭', 1),
('MARRIAGE', '遗嘱', '立遗嘱人：${立遗嘱人}\n\n本人为避免日后纠纷，特立本遗嘱，对本人名下财产作如下处理：\n\n一、财产明细：\n${财产明细}\n\n二、财产分配：\n${财产分配}\n\n本遗嘱由本人亲笔书写并签名，自本人去世后生效。\n\n立遗嘱人：${立遗嘱人}\n${日期}', '婚姻家庭', 1),
('LOAN', '担保合同', '债权人：${债权人}\n债务人：${债务人}\n保证人：${保证人}\n\n一、保证方式：${保证方式}（一般保证/连带责任保证）。\n二、保证范围：主债权本金${金额}元及利息、违约金、实现债权的费用。\n三、保证期间：自主债务履行期限届满之日起${保证期间}。\n\n保证人（签字）：\n${日期}', '民间借贷', 1),
('CONTRACT', '技术服务合同', '甲方（委托方）：${甲方}\n乙方（服务方）：${乙方}\n\n一、服务内容：${服务内容}\n二、服务期限：自${起始日期}至${终止日期}。\n三、服务费用：人民币${费用}元，支付方式：${支付方式}。\n四、验收标准：${验收标准}\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '合同协议', 1),
('CONTRACT', '委托合同', '委托人（甲方）：${甲方}\n受托人（乙方）：${乙方}\n\n一、委托事项：${委托事项}\n二、委托权限：${委托权限}\n三、委托期限：自${起始日期}至${终止日期}。\n四、报酬：人民币${报酬}元。\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '合同协议', 1),
('CONTRACT', '承揽合同', '定作人（甲方）：${甲方}\n承揽人（乙方）：${乙方}\n\n一、承揽项目：${承揽项目}\n二、报酬：人民币${报酬}元。\n三、交付时间：${交付时间}\n四、验收标准：${验收标准}\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '合同协议', 1),
('CONTRACT', '赠与合同', '赠与人（甲方）：${甲方}\n受赠人（乙方）：${乙方}\n\n一、赠与标的：${赠与标的}\n二、交付时间：${交付时间}\n三、其他约定：${其他约定}\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '合同协议', 1),
('COMPANY', '公司章程（简易）', '第一章 总则\n第一条 依据《中华人民共和国公司法》设立${公司名称}。\n第二条 公司注册资本为人民币${注册资本}元。\n\n第二章 经营范围\n第三条 公司经营范围：${经营范围}\n\n第三章 股东及出资\n第四条 股东：${股东}，出资${出资额}元。\n\n第四章 组织机构\n第五条 公司不设董事会，设执行董事一名；不设监事会，设监事一名。\n\n${其他条款}\n\n全体股东签字：\n${日期}', '公司法务', 1),
('COMPANY', '股权代持协议', '实际出资人（甲方）：${甲方}\n名义股东（乙方）：${乙方}\n\n一、代持标的：${公司名称}的${代持比例}%股权。\n二、甲方实际享有该股权全部权益，乙方仅为名义持有人。\n三、代持期限：自${起始日期}起。\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '公司法务', 1),
('PROPERTY', '房屋租赁合同（住宅）', '出租方（甲方）：${出租方}\n承租方（乙方）：${承租方}\n\n一、房屋坐落：${房屋地址}\n二、租金：每月人民币${租金}元，支付方式：${支付方式}。\n三、租期：自${起始日期}至${终止日期}。\n四、押金：人民币${押金}元。\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '房产纠纷', 1),
('INTELLECTUAL', '著作权许可使用合同', '许可方（甲方）：${许可方}\n被许可方（乙方）：${被许可方}\n\n一、许可作品：${作品名称}\n二、许可权利种类：${许可权利}\n三、许可费：人民币${许可费}元。\n四、许可期限：自${起始日期}至${终止日期}。\n\n甲方（签字）：\n乙方（签字）：\n${日期}', '知识产权', 1),
('TRAFFIC', '交通事故谅解书', '致：${致送机关}\n\n本人系${事故时间}交通事故的${身份}，现就本案达成谅解如下：\n\n一、赔偿情况：对方已赔偿人民币${赔偿金额}元。\n二、本人对对方的行为予以谅解，请求司法机关对其从轻处理。\n\n谅解人：${谅解人}\n${日期}', '交通事故', 1),
('CONSUMER', '消费投诉申请书', '投诉人：${投诉人}\n被投诉人：${被投诉人}\n\n投诉请求：\n${投诉请求}\n\n事实与理由：\n${事实与理由}\n\n此致\n${受理机关}\n\n投诉人：${投诉人}\n${日期}', '消费维权', 1),
('ENFORCEMENT', '执行异议申请书', '异议人：${异议人}\n申请执行人：${申请执行人}\n被执行人：${被执行人}\n\n异议请求：\n请求依法对（${执行案号}）执行案件中的执行标的${执行标的}提出异议并中止对该标的的执行。\n\n事实与理由：\n${事实与理由}\n\n此致\n${法院名称}\n\n异议人：${异议人}\n${日期}', '强制执行', 1);
